import{_ as a,o as t,c as i,a2 as e}from"./chunks/framework.D66Xq0Kv.js";const k=JSON.parse('{"title":"02-2 ABI 与事件：外部程序怎样“听懂”合约","description":"","frontmatter":{},"headers":[],"relativePath":"02-evm/abi.md","filePath":"02-evm/abi.md","lastUpdated":1791601077000}'),n={name:"02-evm/abi.md"};function d(p,s,l,o,h,r){return t(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="_02-2-abi-与事件-外部程序怎样-听懂-合约" tabindex="-1">02-2 ABI 与事件：外部程序怎样“听懂”合约 <a class="header-anchor" href="#_02-2-abi-与事件-外部程序怎样-听懂-合约" aria-label="Permalink to &quot;02-2 ABI 与事件：外部程序怎样“听懂”合约&quot;">​</a></h1><blockquote><p><strong>本课目标</strong>：理解合约源码、合约地址、ABI、函数选择器以及事件之间的关系。先不用写完整 Web3 前端。</p></blockquote><h2 id="先看一个普通-python-接口" tabindex="-1">先看一个普通 Python 接口 <a class="header-anchor" href="#先看一个普通-python-接口" aria-label="Permalink to &quot;先看一个普通 Python 接口&quot;">​</a></h2><p>Flask API 会用路径和 JSON 约定如何传参：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /transfer</span></span>
<span class="line"><span>{&quot;to&quot;: &quot;...&quot;, &quot;amount&quot;: 100}</span></span></code></pre></div><p>但是 EVM 不接收 Flask 风格的 JSON body。合约调用包含要执行的函数信息和按 ABI 规则编码的二进制参数。</p><p><strong>ABI（Application Binary Interface）</strong> 可以把它看作“合约对外暴露的机器可读接口说明”，类似简化版的 OpenAPI，但编码规则不一样。</p><h2 id="三样东西必须分开" tabindex="-1">三样东西必须分开 <a class="header-anchor" href="#三样东西必须分开" aria-label="Permalink to &quot;三样东西必须分开&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名称</th><th>到底是什么</th><th>用途</th></tr></thead><tbody><tr><td>Solidity 源码</td><td>人看的代码，如 <code>Counter.sol</code></td><td>开发、审阅</td></tr><tr><td>Bytecode 字节码</td><td>编译后 EVM 能执行的代码</td><td>部署与执行</td></tr><tr><td>ABI</td><td>描述外部函数、参数和事件的 JSON 结构</td><td>让钱包、脚本和前端知道如何编码/解析</td></tr></tbody></table><p>另外还有 <strong>Contract Address（合约地址）</strong>：相当于“你要调用的是哪一个已部署实例”。只知道 ABI 却没有正确网络与合约地址，也不能找到目标实例。</p><h2 id="函数选择器-selector-是什么" tabindex="-1">函数选择器（selector）是什么？ <a class="header-anchor" href="#函数选择器-selector-是什么" aria-label="Permalink to &quot;函数选择器（selector）是什么？&quot;">​</a></h2><p>假设合约有函数：</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> transfer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">address</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> to</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> amount</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">external</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>这是<strong>函数签名演示</strong>，不是完整可部署合约。</p><p>普通 ABI 函数调用数据的开头是 4 字节 selector。它取自规范化函数签名 <code>transfer(address,uint256)</code> 的 Keccak-256 哈希前 4 字节：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>transfer(address,uint256)</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>    selector = 0xa9059cbb</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>0xa9059cbb | 编码后的地址 | 编码后的金额</span></span></code></pre></div><p>其中固定大小的参数通常按 ABI 规则编码为 32 字节字（word），不足时填充。注意它<strong>不是普通 JSON，也不是简单字符串拼接</strong>。</p><h2 id="用-foundry-的-cast-看一个实际输出" tabindex="-1">用 Foundry 的 cast 看一个实际输出 <a class="header-anchor" href="#用-foundry-的-cast-看一个实际输出" aria-label="Permalink to &quot;用 Foundry 的 cast 看一个实际输出&quot;">​</a></h2><p>不需要钱包、不需要 RPC：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cast</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;transfer(address,uint256)&#39;</span></span></code></pre></div><p>预期输出：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0xa9059cbb</span></span></code></pre></div><p>再试：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cast</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> abi-encode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;f(address,uint256)&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0x0000000000000000000000000000000000000001</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span></span></code></pre></div><p>这会输出一段 <code>0x...</code> 开头的长十六进制数据，用来表示编码后的<strong>参数部分</strong>。这里的 <code>f</code> 只帮助声明参数类型；它不表示你已向链转账。把 selector 和参数数据连接后，才能构成这种函数调用的完整 calldata。</p><h2 id="event-是什么-为什么前端能看到-已经付款" tabindex="-1">event 是什么？为什么前端能看到“已经付款”？ <a class="header-anchor" href="#event-是什么-为什么前端能看到-已经付款" aria-label="Permalink to &quot;event 是什么？为什么前端能看到“已经付款”？&quot;">​</a></h2><p>假设合约定义：</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">event</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Paid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">address</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> indexed</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> buyer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> amount</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>执行 <code>emit Paid(msg.sender, 100);</code> 时，会产生符合事件格式的日志。</p><ul><li><strong>indexed buyer</strong>：可放入日志 topics，方便按地址筛选。</li><li><strong>amount</strong>：未 indexed 的值一般编码到日志 data。</li><li>链下系统可以根据 ABI 解码日志并展示“付款事件”。</li></ul><p>但<strong>看到事件并不代表可以跳过链上状态检查</strong>。索引器可能滞后，也需处理链重组。业务真实性最终仍要结合正确网络、合约地址、交易状态和状态机规则判断。</p><h2 id="交易与调用结果要分开记" tabindex="-1">交易与调用结果要分开记 <a class="header-anchor" href="#交易与调用结果要分开记" aria-label="Permalink to &quot;交易与调用结果要分开记&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名称</th><th>例子</th><th>含义</th></tr></thead><tbody><tr><td>Wallet Address</td><td><code>0x...</code></td><td>谁发起或控制账户</td></tr><tr><td>Contract Address</td><td><code>0x...</code></td><td>调用哪个合约实例</td></tr><tr><td>Transaction Hash</td><td><code>0x...</code></td><td>标识一笔已提交交易</td></tr><tr><td>Receipt</td><td>status / gasUsed / logs</td><td>记录执行结果</td></tr><tr><td>ABI</td><td>函数与事件定义</td><td>用于编码参数、解码结果</td></tr><tr><td>Bytecode</td><td><code>0x6080...</code></td><td>EVM 实际执行的程序代码</td></tr></tbody></table><h2 id="练习-画出从网页到合约的路线" tabindex="-1">练习：画出从网页到合约的路线 <a class="header-anchor" href="#练习-画出从网页到合约的路线" aria-label="Permalink to &quot;练习：画出从网页到合约的路线&quot;">​</a></h2><p>你可以把流程写在学习笔记里：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>前端按钮“增加计数”</span></span>
<span class="line"><span>  → 根据 ABI 知道函数名与参数</span></span>
<span class="line"><span>  → 用合约地址定位实例</span></span>
<span class="line"><span>  → 构造交易并请求用户签名</span></span>
<span class="line"><span>  → RPC 广播并获取交易哈希</span></span>
<span class="line"><span>  → 查回执、确认成功</span></span>
<span class="line"><span>  → 再调用 count() 读取最终状态</span></span></code></pre></div><p>回答三个问题：</p><ol><li>用户拒绝签名，是否应该显示“计数成功”？<strong>不应该。</strong></li><li>拿到交易哈希是否代表数值更新成功？<strong>不一定。</strong></li><li>是否能凭一个事件就随意给数据库记“已到账”？<strong>不能，还需验签/核实来源、状态和确认规则。</strong></li></ol><p><strong>本课验收</strong>：能用自己的话区分源码、ABI、字节码、合约地址、交易哈希、回执与事件。</p><p>下一课：<a href="/03-foundry/">Foundry：用自动化测试证明合约不只是“看起来能跑”</a>。</p>`,40)])])}const g=a(n,[["render",d]]);export{k as __pageData,g as default};
